/// <summary>
/// ADO#89454, CB518, Financial dimension deviations, LalitJ, 25-Oct-2023
/// This class is a common class for code reusability
/// </summary>
class METCopyDimensionMethods
{
}

Method.Source:
    /// <summary>
    /// Case - Current line is of Vendor type and existing ledger line needs to be found within same voucher
    /// </summary>
    /// <param name = "_ledgerJournalTrans">
    /// LedgerJournalTrans record 
    /// </param>
    /// <returns>
    /// Financial dimensions for Main account
    /// </returns>
    public static DimensionDefault getDimensionsFromMainAccountModified(LedgerJournalTrans    _ledgerJournalTrans)
    {
        DimensionDefault        mergedDimensions;
        LedgerJournalTrans      ledgerJournalTransExist;

        select firstonly ledgerJournalTransExist
            where ledgerJournalTransExist.AccountType == LedgerJournalACType::Ledger
            && ledgerJournalTransExist.Voucher == _ledgerJournalTrans.Voucher
            && ledgerJournalTransExist.JournalNum == _ledgerJournalTrans.JournalNum;

        if(ledgerJournalTransExist)
        {
            mergedDimensions    = LedgerDimensionFacade::getDefaultDimensionFromLedgerDimension(ledgerJournalTransExist.LedgerDimension);
        }

        return mergedDimensions;
    }

    /// <summary>
    /// Case - Current line is of Ledger type and existing Vendor type line needs to be found and updated within same voucher
    /// </summary>
    /// <param name = "_ledgerJournalTransOrig">
    /// LedgerJournalTrans record
    /// </param>
    public static void updateDimensionsForMainAccount(ledgerJournalTrans    _ledgerJournalTransOrig)
    {
        LedgerJournalTrans      ledgerJournalTransExist;
        DimensionDefault        mergedDimensions;

        select firstonly forupdate ledgerJournalTransExist
            where ledgerJournalTransExist.AccountType == LedgerJournalACType::Vend
            && ledgerJournalTransExist.Voucher == _ledgerJournalTransOrig.Voucher
            && ledgerJournalTransExist.JournalNum == _ledgerJournalTransOrig.JournalNum;

        if(ledgerJournalTransExist)
        {
            mergedDimensions   = LedgerDimensionFacade::getDefaultDimensionFromLedgerDimension(_ledgerJournalTransOrig.LedgerDimension);
                        
            if(ledgerJournalTransExist.DefaultDimension != mergedDimensions)
            {
                try
                {
                    ttsbegin;
                    ledgerJournalTransExist.DefaultDimension    = mergedDimensions;
                    ledgerJournalTransExist.update();
                    ttscommit;
                }

                catch(Exception::Error)
                {
                    throw Error("@MET:METCopyDimError");
                }
                catch(Exception::CLRError)
                {
                    System.Exception        ex;

                    ex = CLRInterop::getLastException();
                    throw Error(ex.ToString());
                }
            }
        }
    }
